Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('delete records','marks a record for deletion at a certain date or after a condition is met.');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask collector','hides the collector or collectors on a record or group of records until a certain date or condition is met.');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask from ipt','hides a record from sharing with other institutions through the integrated publishing toolkit (IPT). ');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask locality','hides coordinates, verbatim coordinates, lat/long remarks, verbatim locality, specific locality, habitat description, microhabitat, and georeference on a record or group of records until a certain date or condition is met.');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask original field number','hides original field number on a record or group of records until a certain date or condition is met.');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask parts','hides all parts on a record or group of records until a certain date or condition is met.');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask preparator','hides preparator or prerparators on a record or group of records until a certain date or condition is met.');
Insert into CTENCUMBRANCE_ACTION (ENCUMBRANCE_ACTION,ENCUMBRANCE_DESCRIPTION) values ('mask record','hides the entire record or group of records from view until a certain date or condition is met.');
